// Package pluginbench is the plugin bench's data: for every plugin the
// Library offers in both Taut and Slick, how each variant did when it ran
// unmodified in Clack's real plugin host against internal/fakeslack
// (internal/ui's TestPluginBench, .github/workflows/plugin-bench.yml), and
// which one the Library installs. bench.json is generated by
// ./internal/pluginbench/report from a bench run and baked into the build;
// docs/PLUGIN-BENCH.md is the same data as a table.
package pluginbench

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
	"sync"
)

// Schema is bench.json's format version.
const Schema = 1

// Check is one feature check of a scenario.
type Check struct {
	Name   string `json:"name"`
	Pass   bool   `json:"pass"`
	Detail string `json:"detail,omitempty"`
}

// Variant is one system's build of a plugin, measured.
type Variant struct {
	System string `json:"system"` // taut | slick
	ID     string `json:"id"`
	SHA256 string `json:"sha256"` // the Library bundle (its version)
	Size   int64  `json:"size"`   // bundle bytes (renderer + main half)

	Loaded     bool     `json:"loaded"`
	StartError string   `json:"startError,omitempty"`
	Errors     []string `json:"errors,omitempty"` // console errors and warnings, deduplicated
	ErrorCount int      `json:"errorCount"`
	Checks     []Check  `json:"checks"`
	Patched    []string `json:"patched,omitempty"` // components it patches
	Roots      int      `json:"roots"`             // host trees it delivered while the scenario ran

	InitMS      float64 `json:"initMs"`      // install + enable until running
	FrameUS     float64 `json:"frameUs"`     // median layout time per frame, scrolling the 500-message channel
	FrameP95US  float64 `json:"frameP95Us"`  // 95th percentile of the same
	BaseFrameUS float64 `json:"baseFrameUs"` // the same pass before the plugin was installed
	ScrollCPUMS float64 `json:"scrollCpuMs"` // process CPU over the scroll pass (layout + JS renders)
	BaseCPUMS   float64 `json:"baseCpuMs"`
	AllocsFrame float64 `json:"allocsFrame"` // Go allocations per frame in the pass
	BaseAllocs  float64 `json:"baseAllocs"`
	JSHeapKB    float64 `json:"jsHeapKb"` // QuickJS heap growth from installing it
	GoHeapKB    float64 `json:"goHeapKb"` // live Go heap growth

	IdleDeliveries int     `json:"idleDeliveries"` // host trees delivered over the idle window (no input, no events)
	IdleSeconds    float64 `json:"idleSeconds"`
	IdleCPUMS      float64 `json:"idleCpuMs"` // process CPU per second with no frames drawn
	BaseIdleCPUMS  float64 `json:"baseIdleCpuMs"`
	IdleWakeups    int     `json:"idleWakeups"` // idle frames that asked for another frame
	BaseWakeups    int     `json:"baseWakeups"`

	Shot      string  `json:"shot,omitempty"`      // screenshot file (bench artifact)
	PixelDiff float64 `json:"pixelDiff,omitempty"` // share of the scene that differs from the other variant's
}

// Passed counts passing checks.
func (v Variant) Passed() int {
	n := 0
	for _, c := range v.Checks {
		if c.Pass {
			n++
		}
	}
	return n
}

// Rerenders reports a variant that keeps re-rendering with nothing
// happening: ten or more host trees over the idle window, more than two a
// second (a loop delivers hundreds; a lookup settling, a few). That
// disqualifies it (rows that keep getting new trees "spaz").
func (v Variant) Rerenders() bool {
	return v.IdleSeconds > 0 && v.IdleDeliveries >= 10 && float64(v.IdleDeliveries)/v.IdleSeconds > 2
}

// Works is loaded, every check passing, no console errors.
func (v Variant) Works() bool {
	return v.Loaded && v.Passed() == len(v.Checks) && v.ErrorCount == 0 && !v.Rerenders()
}

// FrameCost is the per-frame layout overhead over the plugin-free pass.
func (v Variant) FrameCost() float64 { return math.Max(0, v.FrameUS-v.BaseFrameUS) }

// CPUCost is the scroll pass's CPU over the plugin-free pass.
func (v Variant) CPUCost() float64 { return math.Max(0, v.ScrollCPUMS-v.BaseCPUMS) }

// IdleCost is idle CPU per second over the plugin-free idle window.
func (v Variant) IdleCost() float64 { return math.Max(0, v.IdleCPUMS-v.BaseIdleCPUMS) }

// Plugin is a plugin both systems ship, with the bench's pick.
type Plugin struct {
	Name     string    `json:"name"`
	Variants []Variant `json:"variants"` // taut first
	Winner   string    `json:"winner"`   // taut | slick
	Reason   string    `json:"reason"`
	Notes    string    `json:"notes,omitempty"` // what the scenario couldn't exercise
}

// Variant returns the plugin's variant of a system.
func (p *Plugin) Variant(system string) *Variant {
	for i := range p.Variants {
		if p.Variants[i].System == system {
			return &p.Variants[i]
		}
	}
	return nil
}

// Data is bench.json.
type Data struct {
	Schema    int      `json:"schema"`
	Generated string   `json:"generated"` // RFC 3339
	Run       string   `json:"run,omitempty"`
	Sources   []string `json:"sources,omitempty"` // "taut <commit>", "slick <commit>"
	Plugins   []Plugin `json:"plugins"`
}

//go:embed bench.json
var embedded []byte

var (
	once sync.Once
	data *Data
)

// Load returns the baked-in data (empty when bench.json is absent or bad).
func Load() *Data {
	once.Do(func() {
		var d Data
		if err := json.Unmarshal(embedded, &d); err != nil || d.Schema != Schema {
			d = Data{Schema: Schema}
		}
		data = &d
	})
	return data
}

// Pick is the bench's recommendation for a plugin offered in several systems.
type Pick struct {
	Winner string // system
	Reason string
	Exact  bool // every offered bundle is the version the bench measured
}

// Entry is an offered bundle: its system, id and sha256.
type Entry struct{ System, ID, SHA256 string }

// For finds the bench result for a plugin offered as entries (one per
// system). ok is false when the bench has no data for it.
func (d *Data) For(entries []Entry) (Pick, bool) {
	if d == nil || len(entries) < 2 {
		return Pick{}, false
	}
	for i := range d.Plugins {
		p := &d.Plugins[i]
		match, exact := true, true
		for _, e := range entries {
			v := p.Variant(e.System)
			if v == nil || v.ID != e.ID {
				match = false
				break
			}
			exact = exact && strings.EqualFold(v.SHA256, e.SHA256)
		}
		if match && p.Winner != "" {
			return Pick{Winner: p.Winner, Reason: p.Reason, Exact: exact}, true
		}
	}
	return Pick{}, false
}

// Decide picks a plugin's winner and says why, from the measurements.
//
// Correctness first: a variant that loads beats one that doesn't; one that
// doesn't keep re-rendering beats one that does; more passing checks beat
// fewer; fewer console errors beat more. Between variants that work the
// same, the cheaper one wins on what it costs the user: JS init time,
// frame overhead and CPU over the scroll pass, idle CPU and JS heap, each
// compared only when the difference is past noise. A tie goes to the
// smaller bundle.
func Decide(p *Plugin) {
	t, s := p.Variant("taut"), p.Variant("slick")
	if t == nil || s == nil {
		if len(p.Variants) > 0 {
			p.Winner, p.Reason = p.Variants[0].System, "the only variant measured"
		}
		return
	}
	w, l, why := decide(t, s)
	p.Winner, p.Reason = w.System, why
	_ = l
}

func name(sys string) string {
	if sys == "slick" {
		return "Slick"
	}
	return "Taut"
}

func decide(a, b *Variant) (w, l *Variant, why string) {
	pick := func(x *Variant, reason string) (*Variant, *Variant, string) {
		if x == a {
			return a, b, reason
		}
		return b, a, reason
	}
	other := func(x *Variant) *Variant {
		if x == a {
			return b
		}
		return a
	}
	switch {
	case a.Loaded != b.Loaded:
		x := a
		if b.Loaded {
			x = b
		}
		return pick(x, fmt.Sprintf("the %s version doesn't load", name(other(x).System)))
	case !a.Loaded:
		return pick(a, "neither version loads")
	case a.Rerenders() != b.Rerenders():
		x := a
		if a.Rerenders() {
			x = b
		}
		return pick(x, fmt.Sprintf("the %s version keeps re-rendering while idle", name(other(x).System)))
	}
	pa, pb := a.Passed(), b.Passed()
	if pa != pb {
		x := a
		if pb > pa {
			x = b
		}
		o := other(x)
		lead := fmt.Sprintf("passes %d/%d checks (%s %d/%d)", x.Passed(), len(x.Checks), name(o.System), o.Passed(), len(o.Checks))
		if x.Passed() == len(x.Checks) {
			lead = fmt.Sprintf("works fully (%s passes %d/%d checks)", name(o.System), o.Passed(), len(o.Checks))
		}
		if c := costLine(x, o); c != "" {
			lead += ", " + c
		}
		return pick(x, lead)
	}
	if a.ErrorCount != b.ErrorCount && (a.ErrorCount == 0 || b.ErrorCount == 0) {
		x := a
		if b.ErrorCount < a.ErrorCount {
			x = b
		}
		o := other(x)
		lead := fmt.Sprintf("no console errors (%s logs %d)", name(o.System), o.ErrorCount)
		if c := costLine(x, o); c != "" {
			lead += ", " + c
		}
		return pick(x, lead)
	}
	// same features: the cheaper one
	score := 0 // > 0: a cheaper
	for _, c := range costs(a, b) {
		score += c.sign
	}
	full := "works fully"
	if pa < len(a.Checks) {
		full = fmt.Sprintf("same results (%d/%d checks each)", pa, len(a.Checks))
	}
	var x *Variant
	switch {
	case score > 0:
		x = a
	case score < 0:
		x = b
	default:
		x = a
		if b.Size < a.Size {
			x = b
		}
		o := other(x)
		if c := costLine(x, o); c != "" {
			return pick(x, full+", "+c)
		}
		return pick(x, fmt.Sprintf("%s in both; costs within noise, smaller bundle (%s vs %s)", full, kb(x.Size), kb(o.Size)))
	}
	if c := costLine(x, other(x)); c != "" {
		return pick(x, full+", "+c)
	}
	return pick(x, full+", cheaper overall")
}

type cost struct {
	what string
	sign int // +1: a cheaper, -1: b cheaper
	text string
}

// costs compares a and b on each measure, past noise.
func costs(a, b *Variant) []cost {
	var out []cost
	cmp := func(what string, x, y, floor, ratio float64, unit string, faster bool) {
		lo, hi := math.Min(x, y), math.Max(x, y)
		if hi-lo < floor || hi < lo*ratio {
			return
		}
		sign := 1
		if y < x {
			sign = -1
		}
		var text string
		switch {
		case lo <= 0 || hi/lo >= 10:
			text = fmt.Sprintf("%s %s vs %s", what, fmtUnit(lo, unit), fmtUnit(hi, unit))
		case faster:
			text = fmt.Sprintf("%.1fx faster to %s", hi/lo, what)
		default:
			text = fmt.Sprintf("%.1fx less %s", hi/lo, what)
		}
		out = append(out, cost{what, sign, text})
	}
	cmp("load", a.InitMS, b.InitMS, 5, 1.3, "ms", true)
	cmp("frame overhead", a.FrameCost(), b.FrameCost(), 40, 1.5, "µs", false)
	cmp("scroll CPU", a.CPUCost(), b.CPUCost(), 60, 1.4, "ms", false)
	cmp("idle CPU", a.IdleCost(), b.IdleCost(), 3, 1.5, "ms/s", false)
	cmp("JS memory", a.JSHeapKB, b.JSHeapKB, 64, 1.3, "KB", false)
	return out
}

// costLine is the biggest cost advantage x has over o, as text.
func costLine(x, o *Variant) string {
	var best []string
	for _, c := range costs(x, o) {
		if c.sign > 0 { // x cheaper
			best = append(best, c.text)
		}
	}
	if len(best) == 0 {
		return ""
	}
	if len(best) > 2 {
		best = best[:2]
	}
	return strings.Join(best, ", ")
}

func fmtUnit(v float64, unit string) string {
	switch {
	case v >= 100:
		return fmt.Sprintf("%.0f %s", v, unit)
	case v >= 10:
		return fmt.Sprintf("%.0f %s", v, unit)
	default:
		return fmt.Sprintf("%.1f %s", v, unit)
	}
}

func kb(n int64) string { return fmt.Sprintf("%.1f KB", float64(n)/1024) }

// Sort orders plugins by name.
func (d *Data) Sort() {
	sort.Slice(d.Plugins, func(i, j int) bool { return strings.ToLower(d.Plugins[i].Name) < strings.ToLower(d.Plugins[j].Name) })
	for i := range d.Plugins {
		sort.SliceStable(d.Plugins[i].Variants, func(a, b int) bool { return d.Plugins[i].Variants[a].System == "taut" })
	}
}

// Regressions compares a new run with the committed data: a committed
// winner that no longer loads, now keeps re-rendering, passes fewer checks
// than it did, or lost to the other variant on correctness.
func Regressions(old, cur *Data) []string {
	var out []string
	for i := range old.Plugins {
		op := &old.Plugins[i]
		var np *Plugin
		for j := range cur.Plugins {
			if cur.Plugins[j].Name == op.Name {
				np = &cur.Plugins[j]
			}
		}
		if np == nil {
			continue // no longer offered in both
		}
		ow, nw := op.Variant(op.Winner), np.Variant(op.Winner)
		if ow == nil || nw == nil {
			continue
		}
		switch {
		case ow.Loaded && !nw.Loaded:
			out = append(out, fmt.Sprintf("%s: the %s winner no longer loads (%s)", op.Name, name(op.Winner), nw.StartError))
		case !ow.Rerenders() && nw.Rerenders():
			out = append(out, fmt.Sprintf("%s: the %s winner now re-renders while idle (%d trees in %.0fs)", op.Name, name(op.Winner), nw.IdleDeliveries, nw.IdleSeconds))
		case nw.Passed() < ow.Passed():
			var failed []string
			for _, c := range nw.Checks {
				if !c.Pass {
					failed = append(failed, c.Name)
				}
			}
			out = append(out, fmt.Sprintf("%s: the %s winner passes %d checks, was %d (failing: %s)", op.Name, name(op.Winner), nw.Passed(), ow.Passed(), strings.Join(failed, ", ")))
		case np.Winner != op.Winner:
			if o := np.Variant(np.Winner); o != nil && (o.Passed() > nw.Passed() || nw.Rerenders() || !nw.Loaded) {
				out = append(out, fmt.Sprintf("%s: %s now beats the %s winner on correctness: %s", op.Name, name(np.Winner), name(op.Winner), np.Reason))
			}
		}
	}
	return out
}
